from collections import defaultdict


def count_exactly_k_distinct(s: str, k: int) -> int:
    def at_most(limit: int) -> int:
        if limit < 0:
            return 0
        freq = defaultdict(int)
        left = total = 0
        for right, c in enumerate(s):
            freq[c] += 1
            while len(freq) > limit:
                freq[s[left]] -= 1
                if freq[s[left]] == 0:
                    del freq[s[left]]
                left += 1
            total += right - left + 1
        return total

    return at_most(k) - at_most(k - 1)
